import { query } from "@/db";

interface ShowcaseAsset {
  id: string;
  label: string;
  title: string;
  brief: string;
}

/**
 * A set we made, on the front page.
 *
 * The argument this service makes — that eleven symbols can come back as one
 * game rather than eleven interpretations of a sentence — is not an argument
 * anyone should accept in prose. It is a thing you look at. So the storefront
 * shows a real pack, generated by the same path a studio's order takes,
 * against the brief printed underneath it.
 *
 * Only packs flagged `showcase` — ours, set by hand. Nothing a customer
 * ordered can appear here.
 */
export default async function Showcase({ limit = 11 }: { limit?: number }) {
  const assets = await query<ShowcaseAsset>(
    `select g.id, g.label, p.title, p.brief
       from generations g
       join asset_packs p on p.id = g.pack_id
      where p.showcase and g.status = 'done' and g.role = 'symbol'
      order by p.created_at desc, g.created_at
      limit $1`,
    [limit],
  ).catch(() => []);

  if (!assets.length) return null;
  const pack = assets[0];

  return (
    <figure style={{ margin: "2.5rem 0 0" }}>
      <ul
        style={{
          listStyle: "none",
          padding: 0,
          margin: 0,
          display: "grid",
          gap: ".75rem",
          gridTemplateColumns: "repeat(auto-fill, minmax(104px, 1fr))",
        }}
      >
        {assets.map((asset) => (
          <li key={asset.id} style={{ textAlign: "center" }}>
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={`/api/generations/${asset.id}/image`}
              alt={asset.label}
              loading="lazy"
              style={{ width: "100%", height: "auto", display: "block" }}
            />
            <span className="muted" style={{ fontSize: ".7em", letterSpacing: ".04em" }}>
              {asset.label}
            </span>
          </li>
        ))}
      </ul>
      <figcaption className="muted" style={{ fontSize: ".85em", marginTop: ".75rem", maxWidth: "70ch" }}>
        {pack.title} — {pack.brief}
      </figcaption>
    </figure>
  );
}
